import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.O93z6AWZ.js";const s="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/01_eda_overview_en.png",i="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/04_shap_summary_en.png",m=JSON.parse('{"title":"Case Study: Heart Failure (Chapter 2)","description":"","frontmatter":{"title":"Case Study: Heart Failure (Chapter 2)"},"headers":[],"relativePath":"en/labs_chuyen_de/ch02_suy_tim_risk_dxai.md","filePath":"en/labs_chuyen_de/ch02_suy_tim_risk_dxai.md"}'),n={name:"en/labs_chuyen_de/ch02_suy_tim_risk_dxai.md"};function l(c,e,d,h,g,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="chapter-2-case-study-predicting-heart-failure-mortality-heart-failure-clinical-records" tabindex="-1">Chapter 2 Case Study: Predicting Heart Failure Mortality (Heart Failure Clinical Records) <a class="header-anchor" href="#chapter-2-case-study-predicting-heart-failure-mortality-heart-failure-clinical-records" aria-label="Permalink to &quot;Chapter 2 Case Study: Predicting Heart Failure Mortality (Heart Failure Clinical Records)&quot;">​</a></h1><p>Applies the theory from <a href="/hmyt-book/ch02">Chapter 2 — Medical Data Exploration &amp; Preprocessing</a><em>(lecture chapters remain Vietnamese-only — see <a href="/hmyt-book/">Full Course</a>)</em> to a real, runnable clinical problem: predicting mortality in heart failure patients from 12 tabular clinical features. This uses the same dataset as <a href="/hmyt-book/en/du_an/suy_tim_risk_dxai">Project 3.4 — Rapid Heart Failure</a>.</p><div class="danger custom-block"><p class="custom-block-title">⚠️ Not a valid submission for Project 3.4</p><p>Project 3.4 keeps its solution source code <strong>Private</strong> under a Zero-Code Policy so students code it themselves (see the <a href="/hmyt-book/du_an/suy_tim_risk_dxai_lab">Project 3.4 Lab Manual</a> — Vietnamese only for now). The 4 notebooks below are the <strong>course&#39;s public illustrative solution</strong> — if you were assigned Project 3.4 for a grade, this is NOT a valid submission.</p></div><div class="tip custom-block"><p class="custom-block-title">Real data, not simulated</p><p>Unlike the 8 Code Labs in the <a href="/hmyt-book/labs">Code Lab Bank</a> (which use synthetic data via <code>np.random.seed</code>), this case study runs on the real <a href="https://archive.ics.uci.edu/dataset/519/heart+failure+clinical+records" target="_blank" rel="noreferrer">Heart Failure Clinical Records</a> dataset (UCI #519, CC BY 4.0, 299 patients) — every number below comes directly from one real execution of the notebooks, not adjusted to match the literature.</p></div><h2 id="run-online-—-step-by-step-or-all-at-once" tabindex="-1">Run Online — Step by Step or All at Once <a class="header-anchor" href="#run-online-—-step-by-step-or-all-at-once" aria-label="Permalink to &quot;Run Online — Step by Step or All at Once&quot;">​</a></h2><p>Each notebook below <strong>downloads its own data and installs any missing libraries</strong> (<code>imbalanced-learn</code>, <code>shap</code>) when opened via Colab/Kaggle — click a button, choose <strong>Runtime → Run all</strong>, and it runs immediately, no local environment setup needed. To work <strong>step by step</strong>: open each notebook in turn. To run the <strong>entire lab</strong>: open and &quot;Run all&quot; in sequence <code>1_eda</code> → <code>2_baseline</code> → <code>3_improvement</code> → <code>4_xai</code> (each notebook reloads the data and reproduces the previous step on its own, no dependency on another notebook&#39;s live state).</p><table tabindex="0"><thead><tr><th>Notebook</th><th style="text-align:center;">Colab</th><th style="text-align:center;">Kaggle</th></tr></thead><tbody><tr><td><code>1_eda.ipynb</code></td><td style="text-align:center;"><a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/1_eda.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a></td><td style="text-align:center;"><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/1_eda.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></td></tr><tr><td><code>2_baseline.ipynb</code></td><td style="text-align:center;"><a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/2_baseline.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a></td><td style="text-align:center;"><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/2_baseline.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></td></tr><tr><td><code>3_improvement.ipynb</code></td><td style="text-align:center;"><a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/3_improvement.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a></td><td style="text-align:center;"><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/3_improvement.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></td></tr><tr><td><code>4_xai.ipynb</code></td><td style="text-align:center;"><a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/4_xai.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a></td><td style="text-align:center;"><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/4_xai.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></td></tr></tbody></table><blockquote><p>The Colab links point to the public mirror on <code>hmyt-book</code> (the source repo <code>HMYT</code> is Private, so Colab cannot read from it directly) — the content is identical to the source repo, synced one-way automatically.</p></blockquote><h2 id="dataset-underlying-literature" tabindex="-1">Dataset &amp; Underlying Literature <a class="header-anchor" href="#dataset-underlying-literature" aria-label="Permalink to &quot;Dataset &amp; Underlying Literature&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Dataset</strong></td><td>Heart Failure Clinical Records (UCI #519) — 299 patients, 13 features, <strong>no missing values</strong></td></tr><tr><td><strong>Label</strong></td><td>Binary <code>DEATH_EVENT</code> — 203 survived (67.9%) / 96 died (32.1%)</td></tr><tr><td><strong>Step 2 benchmark</strong></td><td><code>chicco2020machine</code> — Random Forest, Accuracy 74.0%, MCC 0.384</td></tr><tr><td><strong>Step 3 benchmark</strong></td><td><code>ishaq2021improving</code> — Extra Trees + SMOTE, Accuracy 92.6%</td></tr><tr><td><strong>Background review</strong></td><td><code>mpanya2021predicting</code> — systematic review of 30 ML studies for heart failure</td></tr></tbody></table><h2 id="step-1-—-exploration-data-preparation" tabindex="-1">Step 1 — Exploration &amp; Data Preparation <a class="header-anchor" href="#step-1-—-exploration-data-preparation" aria-label="Permalink to &quot;Step 1 — Exploration &amp; Data Preparation&quot;">​</a></h2><p>Applies Section 2.3 (EDA), 2.4 (mathematical foundations of scaling), 2.5 (Rubin&#39;s theory of missing data — illustrated separately since the original data has none), 2.6 (4-step leakage-free pipeline), 2.7 (real-world clinical data conventions).</p><p><img src="'+s+'" alt="EDA overview: label distribution and correlation matrix"></p><p><strong>Result:</strong> no missing values in the original data; moderate label imbalance (32.1% deaths); Train/Test split 239/60 via <code>stratify=True</code>, <code>random_state=42</code>.</p><p>👉 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/1_eda.ipynb">Download <code>1_eda.ipynb</code></a>   <a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/1_eda.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/1_eda.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></p><h2 id="step-2-—-reproducing-the-original-literature-baseline" tabindex="-1">Step 2 — Reproducing the Original Literature (Baseline) <a class="header-anchor" href="#step-2-—-reproducing-the-original-literature-baseline" aria-label="Permalink to &quot;Step 2 — Reproducing the Original Literature (Baseline)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th style="text-align:center;">Accuracy</th><th style="text-align:center;">MCC</th><th style="text-align:center;">F1</th></tr></thead><tbody><tr><td>Logistic Regression</td><td style="text-align:center;">0.8167</td><td style="text-align:center;">0.5563</td><td style="text-align:center;">0.6667</td></tr><tr><td>Random Forest</td><td style="text-align:center;">0.8167</td><td style="text-align:center;">0.5563</td><td style="text-align:center;">0.6667</td></tr><tr><td><strong><code>chicco2020machine</code> (literature)</strong></td><td style="text-align:center;">0.7400</td><td style="text-align:center;">0.3840</td><td style="text-align:center;">—</td></tr></tbody></table><p>The Random Forest baseline in this notebook <strong>exceeds</strong> the literature benchmark (+7.67 pp Accuracy). Logistic Regression and Random Forest produce identical summary metrics despite disagreeing on 4/60 patients — a coincidence at the aggregate level caused by the small Test size (n=60), not an error.</p><p>👉 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/2_baseline.ipynb">Download <code>2_baseline.ipynb</code></a>   <a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/2_baseline.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/2_baseline.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></p><h2 id="step-3-—-optimization-with-smote" tabindex="-1">Step 3 — Optimization with SMOTE <a class="header-anchor" href="#step-3-—-optimization-with-smote" aria-label="Permalink to &quot;Step 3 — Optimization with SMOTE&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Configuration</th><th style="text-align:center;">Accuracy</th><th style="text-align:center;">MCC</th><th style="text-align:center;">F1</th></tr></thead><tbody><tr><td>Extra Trees (no SMOTE)</td><td style="text-align:center;">0.7500</td><td style="text-align:center;">0.3685</td><td style="text-align:center;">0.4828</td></tr><tr><td>Extra Trees + SMOTE</td><td style="text-align:center;">0.7667</td><td style="text-align:center;">0.4182</td><td style="text-align:center;">0.5333</td></tr><tr><td><strong><code>ishaq2021improving</code> (literature)</strong></td><td style="text-align:center;">0.9260</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Result below the literature benchmark — and that&#39;s the real lesson</p><p>The SMOTE + Extra Trees configuration here <strong>does not reproduce</strong> the 92.6% benchmark — it even falls short of the Step 2 baseline. The most likely cause: the paper uses 100×10-fold cross-validation (far more stable) while this notebook uses a single, fixed Train/Test split on a very small sample (Test = 60 patients). This is a genuine illustration of the risk of directly comparing a single split against repeated-CV results — not a bug to &quot;fix&quot; until the published number matches.</p></div><p>👉 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/3_improvement.ipynb">Download <code>3_improvement.ipynb</code></a>   <a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/3_improvement.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/3_improvement.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></p><h2 id="step-4-—-explainability-xai-with-shap" tabindex="-1">Step 4 — Explainability (XAI) with SHAP <a class="header-anchor" href="#step-4-—-explainability-xai-with-shap" aria-label="Permalink to &quot;Step 4 — Explainability (XAI) with SHAP&quot;">​</a></h2><p><img src="'+i+'" alt="SHAP summary plot"></p><p>Mean |SHAP| ranking (Top 5/13): <code>time</code> (1) → <code>ejection_fraction</code> (2) → <code>serum_creatinine</code> (3) → <code>age</code> (4) → <code>serum_sodium</code> (5).</p><p><code>ejection_fraction</code> and <code>serum_creatinine</code> — the two indicators the literature identifies as most decisive — <strong>both land in the Top 5</strong>. The single highest-ranked SHAP feature (<code>time</code>) reflects clinical follow-up duration and needs careful interpretation (it is not a direct physiological measurement).</p><p>👉 <a href="/hmyt-book/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/4_xai.ipynb">Download <code>4_xai.ipynb</code></a>   <a href="https://colab.research.google.com/github/fossbk-spec/hmyt-book/blob/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/4_xai.ipynb" target="_blank" rel="noreferrer"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Colab"></a><a href="https://www.kaggle.com/kernels/welcome?src=https://raw.githubusercontent.com/fossbk-spec/hmyt-book/gh-pages/labs_chuyen_de/ch02_suy_tim_risk_dxai/en/4_xai.ipynb" target="_blank" rel="noreferrer"><img src="https://kaggle.com/static/images/open-in-kaggle.svg" alt="Kaggle"></a></p><h2 id="step-5-—-report" tabindex="-1">Step 5 — Report <a class="header-anchor" href="#step-5-—-report" aria-label="Permalink to &quot;Step 5 — Report&quot;">​</a></h2><p>A filled-in report template with real numbers (not placeholder data) is available in the source repo at <code>labs_chuyen_de/ch02_suy_tim_risk_dxai/report/5_report_outline_en.md</code>.</p><hr><p><em>Full source code + data + <code>requirements.txt</code> environment:</em><code>labs_chuyen_de/ch02_suy_tim_risk_dxai/</code> <em>in the <code>fossbk-spec/HMYT</code> repo (English notebooks under <code>notebooks_en/</code>).</em></p>',32)])])}const _=t(n,[["render",l]]);export{m as __pageData,_ as default};
